#include <bits/stdc++.h>
using namespace std;
int main(){
    int T; scanf("%d",&T);
    while(T--){
        int n; scanf("%d",&n);
        vector<int> pos(n+2,0);
        for(int i=0;i<n;i++){int x; scanf("%d",&x); pos[x]=i;}
        // bad[i]=1 if pos[i]>pos[i+1]
        vector<int> pre(n+2,0);
        for(int i=1;i<=n;i++){
            int bad = (i+1<=n && pos[i]>pos[i+1]) ? 1 : 0;
            pre[i]=pre[i-1]+bad;
        }
        int ans=0;
        for(int t=0;t<=n/2;t++){
            int l=t+1, r=n-t;
            if(r-l+1<=1){ans=t;break;}
            // need no bad index in [l, r-1]
            if(pre[r-1]-pre[l-1]==0){ans=t;break;}
        }
        printf("%d\n",ans);
    }
}

