int r[50005][5];
int n;
bool sup(int x,int y){int c=0; for(int j=0;j<5;j++) if(r[x][j]<r[y][j]) c++; return c>=3;}
int main(){
    int T; scanf("%d",&T);
    while(T--){
        scanf("%d",&n);
        for(int i=0;i<n;i++) for(int j=0;j<5;j++) scanf("%d",&r[i][j]);
        int cand=0;
        for(int i=1;i<n;i++) if(sup(i,cand)) cand=i;
        bool ok=true;
        for(int i=0;i<n&&ok;i++) if(i!=cand && !sup(cand,i)) ok=false;
        printf("%d\n", ok? cand+1 : -1);
    }
}

