#include <bits/stdc++.h>
using namespace std;
vector<int> par;
int find(int x){ while(par[x]!=x){ par[x]=par[par[x]]; x=par[x]; } return x; }
void unite(int a,int b){ a=find(a); b=find(b); if(a!=b) par[a]=b; }
int main(){
    int T; scanf("%d",&T);
    while(T--){
        int n,k; scanf("%d %d",&n,&k);
        string s,t; cin>>s>>t;
        par.assign(n,0); for(int i=0;i<n;i++) par[i]=i;
        for(int i=0;i<n;i++){
            if(i+k<n) unite(i,i+k);
            if(i+k+1<n) unite(i,i+k+1);
        }
        vector<int> diff((size_t)n*26,0);
        for(int i=0;i<n;i++){
            int r=find(i);
            diff[(size_t)r*26+(s[i]-'a')]++;
            diff[(size_t)r*26+(t[i]-'a')]--;
        }
        bool ok=true;
        for(size_t j=0;j<diff.size()&&ok;j++) if(diff[j]!=0) ok=false;
        puts(ok?"YES":"NO");
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n);
        vector<long long> w(n+1);
        long long base=0;
        for(int i=1;i<=n;i++){ scanf("%lld",&w[i]); base+=w[i]; }
        vector<int> deg(n+1,0);
        for(int i=0;i<n-1;i++){ int a,b; scanf("%d %d",&a,&b); deg[a]++; deg[b]++; }
        vector<long long> gain;           // vertex v contributes deg(v)-1 copies of w[v]
        for(int v=1;v<=n;v++) for(int c=0;c<deg[v]-1;c++) gain.push_back(w[v]);
        sort(gain.rbegin(), gain.rend());
        long long acc=base;
        for(int k=1;k<=n-1;k++){
            if(k>1) acc+=gain[k-2];
            printf("%lld%c", acc, k==n-1?'\n':' ');
        }
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n);
        // beats[u][v]: u wins against v (for non-tie pairs); tie pairs marked separately
        vector<vector<int>> res(n, vector<int>(n,0));   // res[u][v]=1 means u beat v
        vector<vector<int>> tie(n, vector<int>(n,0));
        if(n%2==1){
            for(int u=0;u<n;u++) for(int v=0;v<n;v++) if(u!=v){
                int d=(v-u+n)%n;
                if(d>=1 && d<=(n-1)/2) res[u][v]=1;
            }
        } else {
            for(int a=0;a<n;a+=2){ tie[a][a+1]=tie[a+1][a]=1; }
            vector<vector<int>> avail(n, vector<int>(n,0));
            for(int u=0;u<n;u++) for(int v=0;v<n;v++) if(u!=v && !tie[u][v]) avail[u][v]=1;
            // greedy closed walks: every vertex has even available degree, so each walk closes
            for(int s=0;s<n;s++){
                while(true){
                    int cur=s; bool moved=false;
                    while(true){
                        int nxt=-1;
                        for(int v=0;v<n;v++) if(avail[cur][v]){ nxt=v; break; }
                        if(nxt<0) break;
                        avail[cur][nxt]=avail[nxt][cur]=0;
                        res[cur][nxt]=1;
                        cur=nxt; moved=true;
                    }
                    if(!moved) break;
                }
            }
        }
        string line;
        for(int x=0;x<n;x++) for(int y=x+1;y<n;y++){
            int val;
            if(tie[x][y]) val=0;
            else if(res[x][y]) val=1;
            else val=-1;
            line += to_string(val);
            if(!(x==n-2 && y==n-1)) line += ' ';
        }
        if(n==2) line = "0";
        puts(line.c_str());
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; long long k; scanf("%d %lld",&n,&k);
        int m=n+1;                                  // permutation of 0..n (prefix sums)
        long long total=(long long)m*(m-1)/2;
        long long need=total-k;                     // required inversions
        vector<int> avail(m); iota(avail.begin(),avail.end(),0);
        vector<int> perm;
        for(int i=0;i<m;i++){
            int left=m-1-i;                         // max Lehmer digit at position i
            int c=(int)min<long long>(need,left);
            need-=c;
            perm.push_back(avail[c]);
            avail.erase(avail.begin()+c);
        }
        for(int i=1;i<m;i++) printf("%d%c", perm[i]-perm[i-1], i==m-1?'\n':' ');
    }
}

