#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; long long c,d;
        scanf("%d %lld %lld",&n,&c,&d);
        vector<long long> a(n);
        for(auto &x:a) scanf("%lld",&x);
        sort(a.rbegin(),a.rend());
        vector<long long> pre(n+1,0);
        for(int i=0;i<n;i++) pre[i+1]=pre[i]+a[i];
        if(pre[min<long long>(n,d)]>=c){ puts("Infinity"); continue; }
        // value(k): L=k+1 days per cycle, top min(n,L) quests repeat each block
        auto value=[&](long long k)->long long{
            long long L=k+1;
            long long full=d/L, rem=d%L;
            return full*pre[min<long long>(n,L)] + pre[min<long long>(n,rem)];
        };
        if(value(0)<c){ puts("Impossible"); continue; }
        long long lo=0, hi=d-1;                 // value nonincreasing in k; find largest k with value>=c
        while(lo<hi){
            long long mid=(lo+hi+1)/2;
            if(value(mid)>=c) lo=mid; else hi=mid-1;
        }
        printf("%lld\n",lo);
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; scanf("%d",&n);
    vector<pair<long long,int>> ev;           // (time, type): start=0 before end=1 at same time (closed intervals)
    for(int i=0;i<n;i++){
        long long l,r; scanf("%lld %lld",&l,&r);
        ev.push_back({l,0});
        ev.push_back({r,1});
    }
    sort(ev.begin(),ev.end(),[](const pair<long long,int>&x,const pair<long long,int>&y){
        if(x.first!=y.first) return x.first<y.first;
        return x.second<y.second;               // starts (0) before ends (1)
    });
    int cur=0, best=0;
    for(auto &e:ev){
        if(e.second==0){ cur++; best=max(best,cur); }
        else cur--;
    }
    puts(best<=2 ? "YES" : "NO");
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    long long n,a,b,k; scanf("%lld %lld %lld %lld",&n,&a,&b,&k);
    vector<long long> cost;
    for(int i=0;i<n;i++){
        long long h; scanf("%lld",&h);
        long long r=h%(a+b);
        if(r==0) r=a+b;                          // remainder in 1..a+b
        cost.push_back((r+a-1)/a - 1);           // skips needed so we land the killing hit
    }
    sort(cost.begin(),cost.end());
    long long pts=0;
    for(long long c:cost){
        if(c<=k){ k-=c; pts++; }
        else break;
    }
    printf("%lld\n",pts);
}

