    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n);
        vector<long long> a(n);
        for(auto &x:a) scanf("%lld",&x);
        long long D=0, mn=LLONG_MAX, mx=LLONG_MIN;
        for(int i=0;i+1<n;i++) if(a[i]!=-1 && a[i+1]!=-1) D=max(D,llabs(a[i]-a[i+1]));
        for(int i=0;i<n;i++) if(a[i]==-1){
            if(i>0 && a[i-1]!=-1){ mn=min(mn,a[i-1]); mx=max(mx,a[i-1]); }
            if(i+1<n && a[i+1]!=-1){ mn=min(mn,a[i+1]); mx=max(mx,a[i+1]); }
        }
        if(mn==LLONG_MAX){ printf("0 0\n"); continue; }   // all missing
        long long m=max(D,(mx-mn+1)/2);
        long long k=(mn+mx)/2;
        printf("%lld %lld\n", m, k);
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n);
        vector<long long> b(2*n);
        for(auto &x:b) scanf("%lld",&x);
        sort(b.begin(),b.end());
        long long M=b[2*n-1];                       // a_1 = max element of b
        // rest: b' = b without M (2n-1 elements, ascending). P' = n-1 smallest, N' = n largest.
        vector<long long> P(b.begin(), b.begin()+(n-1)), N(b.begin()+(n-1), b.begin()+(2*n-1));
        long long e=M;
        for(long long x:N) e+=x;
        for(long long x:P) e-=x;                    // e = M + sum(N') - sum(P') > M, so new and distinct
        printf("%lld %lld", M, e);
        for(int i=0;i<n;i++){
            printf(" %lld", N[i]);
            if(i<n-1) printf(" %lld", P[i]);
        }
        printf("\n");
    }
}

