int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n);
        vector<int> a(n);
        for(auto &x:a) scanf("%d",&x);
        long long total=0;
        vector<int> cnt(n+1,0);
        while(true){
            long long s=0; for(int x:a) s+=x;
            if(s==0) break;
            total+=s;
            // new a_i = MAD of prefix a_1..a_i
            fill(cnt.begin(),cnt.end(),0);
            int mad=0;
            for(int i=0;i<n;i++){
                cnt[a[i]]++;
                if(a[i]>0 && cnt[a[i]]>=2 && a[i]>mad) mad=a[i];
                a[i]=mad;
            }
        }
        printf("%lld\n", total);
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int q; scanf("%d",&q);
    multiset<int> ls, rs;                      // all segments are pairwise intersecting iff max l <= min r
    while(q--){
        char op[4]; int l,r;
        scanf("%s %d %d",op,&l,&r);
        if(op[0]=='+'){ ls.insert(l); rs.insert(r); }
        else { ls.erase(ls.find(l)); rs.erase(rs.find(r)); }
        bool yes = ls.size()>=2 && *ls.rbegin() > *rs.begin();
        puts(yes?"YES":"NO");
    }
}

