int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n);
        vector<long long> a(n);
        for(auto &x:a) scanf("%lld",&x);
        long long cur=2000000000LL, ops=0;       // cur = smallest piece of the right part
        for(int i=n-1;i>=0;i--){
            long long k=(a[i]+cur-1)/cur;        // fewest pieces so the largest piece <= cur
            ops+=k-1;
            cur=a[i]/k;                          // best smallest piece for the left side
        }
        printf("%lld\n",ops);
    }
}

