#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n);
        vector<string> w(n);
        static char buf[400005];
        for(auto &s:w){ scanf("%s",buf); s=buf; }
        int best=0;
        for(char c='a';c<='e';c++){
            vector<int> v;                       // value per word: (count of c) - (count of others)
            for(auto &s:w){
                int cnt=0; for(char ch:s) if(ch==c) cnt++;
                v.push_back(2*cnt-(int)s.size());
            }
            sort(v.rbegin(),v.rend());
            long long sum=0; int k=0;
            for(int x:v){ if(sum+x>0){ sum+=x; k++; } else break; }
            best=max(best,k);
        }
        printf("%d\n",best);
    }
}
